```javascript
import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, vec3, smoothstep, hash, fract, texture, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, Color, LinearFilter } = ctx.THREE;

  const group = new Group();
  const content = new Group();
  group.add(content);

  // === Colors from spec ===
  const colors = config.colors ?? config.intent?.visualSpec?.colors ?? {};
  const inkCol = new Color(colors.ink ?? '#16161d');
  const paperStr = colors.paper ?? '#e8ecf2';
  const accentCol = new Color(colors.accent ?? '#ff2a38');
  const surfaceCol = new Color(colors.surface ?? '#0b0b10');

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  // Entrance fade uniform (animated by GSAP)
  const fadeU = uniform(0);

  // === STAGE: engineered gradient backdrop + subtle grain ===
  const backdropMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  const gUv = uv();
  const baseGrad = mix(vec3(surfaceCol), vec3(inkCol), smoothstep(0.0, 1.0, gUv.y));
  const accentZone = smoothstep(0.42, 0.32, gUv.y).mul(smoothstep(0.26, 0.32, gUv.y));
  const gradAccent = mix(baseGrad, vec3(accentCol), accentZone.mul(0.10));
  const grain = hash(fract(gUv.mul(950.0)));
  backdropMat.colorNode = gradAccent.add(grain.mul(0.012)).mul(fadeU);

  const backdrop = new Mesh(new PlaneGeometry(7, 6), backdropMat);
  backdrop.position.z = -2.5;
  content.add(backdrop);

  // === Image plane (feature-card.png) ===
  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  let imageMesh = null;
  let imageMat = null;

  if (imageUrl) {
    imageMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
    imageMat.colorNode = mix(vec3(surfaceCol), vec3(inkCol), smoothstep(0.0, 1.0, uv())).mul(fadeU);
    imageMesh = new Mesh(new PlaneGeometry(3.5, 2.2), imageMat);
    imageMesh.position.set(0, -0.3, -0.8);
    content.add(imageMesh);

    ctx.textureLoader.loadTexture(imageUrl).then((tex) => {
      tex.minFilter = LinearFilter;
      tex.magFilter = LinearFilter;
      imageMat.colorNode = texture(tex, uv()).rgb.mul(fadeU);
      imageMat.needsUpdate = true;
    });
  }

  // === Text: "Collection" headline ===
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: 0.42,
      color: paperStr,
      align: 'center'
    });
    txt.position.set(0, 0.55, 0.0);
    content.add(txt);
  }

  // === Accent underline (signal red, <=10% of frame) ===
  const accentMat = new MeshBasicNodeMaterial({ transparent: true, depthWrite: false });
  accentMat.colorNode = vec3(accentCol).mul(fadeU);
  const accentBar = new Mesh(new PlaneGeometry(0.55, 0.018), accentMat);
  accentBar.position.set(0, 0.08, 0.01);
  content.add(accentBar);

  // === Entrance animation: rise-in + weighted-settle ===
  const tl = gsap.timeline();
  content.position.y = 0.4;
  content.scale.set(0.96, 0.96, 0.96);

  tl.to(fadeU, { value: 1, duration: 0.6, ease: 'power2.out' });
  tl.to(content.position, { y: 0, duration: 0.7, ease: 'power3.out' }, 0);
  tl.to(content.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.6, ease: 'power3.out' }, 0);
  tl.to(content.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' }, 0.6);

  // === Cleanup ===
  group.userData.cleanup = () => {
    tl.kill();
    backdropMat.dispose();
    backdrop.geometry.dispose();
    if (imageMat) imageMat.dispose();
    if (imageMesh) imageMesh.geometry.dispose();
    accentMat.dispose();
    accentBar.geometry.dispose();
  };

  group.userData.handlers = {};

  return group;
}
